'use strict';
// Run without downloading packages: node tests/share-card-20260911.cjs
// Checks output contracts and card geometry. This is not a real-browser UI test.
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const ROOT=path.resolve(__dirname,'..');
function canvas(){const rec={text:[],rotations:[],images:[],scales:[]};const c={font:'20px serif',textAlign:'left',canvas:null,save(){},restore(){},scale(...v){rec.scales.push(v)},rotate(v){rec.rotations.push(v)},translate(){},beginPath(){},moveTo(){},arcTo(){},closePath(){},lineTo(){},quadraticCurveTo(){},bezierCurveTo(){},arc(){},ellipse(){},fill(){},stroke(){},clip(){},fillRect(){},createLinearGradient(){return{addColorStop(){}}},createRadialGradient(){return{addColorStop(){}}},measureText(s){const size=Number(this.font.match(/([\d.]+)px/)?.[1]||20);return{width:Array.from(String(s)).reduce((a,ch)=>a+(/[\x00-\x7f]/.test(ch)?size*.52:size),0)}},fillText(s,x,y){assert(Number.isFinite(x)&&Number.isFinite(y));rec.text.push({s:String(s),x,y,font:this.font,align:this.textAlign})},drawImage(...a){rec.images.push(a)}};const cv={width:0,height:0,getContext:()=>c,_rec:rec};c.canvas=cv;return cv;}
class Img{constructor(){this.width=this.naturalWidth=400;this.height=this.naturalHeight=600}set src(v){this._src=v;queueMicrotask(()=>this.onload&&this.onload())}get src(){return this._src}}
const ctx={window:{},Image:Img,URL,location:{origin:'https://preview.invalid'},document:{baseURI:'https://preview.invalid/preview-share.html',currentScript:{src:'https://preview.invalid/JS/share-card.js'},fonts:null,createElement:t=>{assert.equal(t,'canvas');return canvas()}},setTimeout,clearTimeout,console};ctx.window=ctx;vm.createContext(ctx);vm.runInContext(fs.readFileSync(path.join(ROOT,'JS/share-card.js'),'utf8'),ctx);const A=ctx.JYShareCard;
function cards(n,source){return Array.from({length:n},(_,i)=>({name:'牌'+String(i+1).padStart(2,'0'),pos:'位置'+(i+1),img:'card-'+i+'.png',sourceProfile:source||'gd_book_t',reversed:i===1}));}
function loc(cv,n){return cv._rec.text.find(t=>t.s==='牌'+String(n).padStart(2,'0'))}
let passed=0;async function test(name,fn){await fn();passed++;console.log('✓ '+name)}
(async()=>{
 await test('Ten card types and the public render/download APIs exist',()=>{assert.equal(A.types.length,10);['invite','bazi','baziPersonality','baziCompatibility','ziwei','tarot','lenormand','meihua','ootk','oracle'].forEach(t=>assert(A.types.includes(t)));assert.equal(typeof A.download,'function')});
 await test('Rendering preserves source data and produces 2160 × 2700',async()=>{const d={question:'原問題',cards:cards(3,'rws_reversals')};const before=JSON.stringify(d);d.cards.forEach(Object.freeze);Object.freeze(d.cards);Object.freeze(d);const cv=await A.render('tarot',d);assert.equal(cv.width,2160);assert.equal(cv.height,2700);assert.equal(JSON.stringify(d),before)});
 await test('RWS inverse rotates the actual image; Book T does not inherit an inverse',async()=>{const r=await A.render('tarot',{cards:cards(3,'rws_reversals')});assert.equal(r._rec.rotations.filter(x=>x===Math.PI).length,1);assert(r._rec.text.some(t=>t.s.includes('逆位')));const g=await A.render('tarot',{cards:cards(3,'gd_book_t')});assert.equal(g._rec.rotations.filter(x=>x===Math.PI).length,0);assert(!g._rec.text.some(t=>t.s.includes('逆位')))});
 await test('Every tarot card survives the 3–54 card layouts',async()=>{for(const n of [3,5,6,7,10,13,15,21,54]){const cv=await A.render('tarot',{cards:cards(n)});for(let i=1;i<=n;i++){const p=loc(cv,i);assert(p,'missing card '+i+'/'+n);assert(p.x>40&&p.x<1040&&p.y<1125,'card outside image')}assert.equal(cv._rec.images.filter(a=>String(a[0].src).startsWith('card-')).length,n)}});
 await test('Lenormand 3/5 stay on one line; comparison has distinct A/shared/B rows',async()=>{for(const n of [3,5]){const cv=await A.render('lenormand',{cards:cards(n)});assert.equal(new Set(Array.from({length:n},(_,i)=>loc(cv,i+1).y)).size,1)}const cv=await A.render('lenormand',{cards:cards(7)});assert.equal(loc(cv,1).y,loc(cv,3).y);assert(loc(cv,3).y<loc(cv,4).y&&loc(cv,4).y<loc(cv,5).y);assert.equal(loc(cv,5).y,loc(cv,7).y);assert.equal(loc(cv,2).x,loc(cv,4).x);assert.equal(loc(cv,4).x,loc(cv,6).x)});
 await test('Lenormand nine-square and 4×8+4 preserve row order and independent tail',async()=>{const n=await A.render('lenormand',{cards:cards(9)});assert.equal(new Set(Array.from({length:9},(_,i)=>loc(n,i+1).y)).size,3);const g=await A.render('lenormand',{cards:cards(36)});let rows={};for(let i=1;i<=36;i++){const p=loc(g,i);assert(p.x>40&&p.x<1040&&p.y<1125);(rows[p.y]||(rows[p.y]=[])).push(i)}assert.deepEqual(Object.values(rows).map(a=>a.length),[8,8,8,8,4]);assert.deepEqual(Object.values(rows)[4],[33,34,35,36])});
 await test('Missing chart/poem data cannot display a fabricated personal result',async()=>{for(const type of ['bazi','ziwei','tarot','meihua','ootk','oracle']){const cv=await A.render(type,{});assert(cv._rec.text.some(t=>/尚無/.test(t.s)));assert(!cv._rec.text.some(t=>/癸亥|癸未|命宮 ・ 天府/.test(t.s)))}});
 await test('All 60 oracle poems retain their exact four columns, right to left',async()=>{const src=fs.readFileSync(path.join(ROOT,'JS/oracle.js'),'utf8');const poems=Array.from(src.matchAll(/\{n:(\d+),g:"([^"]+)",p:"((?:[^"\\]|\\.)*)"/g));assert.equal(poems.length,60);for(const m of poems){const poem=JSON.parse('"'+m[3]+'"'),cv=await A.render('oracle',{number:m[1],poem});const chars=cv._rec.text.filter(t=>t.x>=230&&t.x<=840&&t.y>=500&&t.y<930&&Array.from(t.s).length===1);let cols={};chars.forEach(t=>(cols[t.x]||(cols[t.x]=[])).push(t));const reconstructed=Object.keys(cols).sort((a,b)=>b-a).map(x=>cols[x].sort((a,b)=>a.y-b.y).map(t=>t.s).join('')).join('\n');assert.equal(reconstructed,poem,'poem '+m[1]);}});
 await test('Long user text is visibly shortened; prompt/result data remains untouched',async()=>{const q='完整問題不應該被分享卡修改'.repeat(60),d={question:q,cards:cards(3)},cv=await A.render('tarot',d);assert.equal(d.question,q);assert(cv._rec.text.some(t=>t.s.endsWith('…')))});
 await test('Oracle buttons use the unified engine; original question/spread callers remain connected',()=>{const o=fs.readFileSync(path.join(ROOT,'JS/oracle.js'),'utf8'),u=fs.readFileSync(path.join(ROOT,'JS/ui.js'),'utf8'),h=fs.readFileSync(path.join(ROOT,'index.html'),'utf8');assert(o.includes("JYShareCard.open('oracle',data)"));assert(o.includes("JYShareCard.download('oracle',data)"));assert(o.includes('poem:_poem.p'));assert(!o.includes('function _drawShareCard('));assert(u.includes('S.tarot.dynamicSpreadDef || S.tarot.spreadDef'));assert(h.includes('JS/share-card.js?v=20260911preview1'));assert(h.includes('assets/share/share-cards-20260911.css'))});
 console.log('share-card-regression: '+passed+' groups passed. Canvas contracts only; real-browser/mobile sharing is a separate gate.');
})().catch(e=>{console.error(e);process.exitCode=1});
